#include <iostream>
#include <vector>
#include <algorithm>

int main() {
    int n, m;
    std::cin >> n >> m;
    std::vector<int> fact(n + 1);
    fact[0] = n;
    for (int i = 1; i < n; i++) {
        long long temp_fact = (long long)fact[i - 1] * (n - i);
        fact[i] = (int)(temp_fact % m);
    }
    int size = n * (n - 1) + 1;
    std::vector<int> dp(size, 0);
    int mid = (n * (n - 1)) / 2;
    std::vector<int> temp(dp);
    dp[mid] = 1;
    int ans = 0;
    for (int i = n - 1; i >= 0; i--) {
        int c = n - 1 - i;
        temp = dp;
        std::fill(dp.begin(), dp.end(), 0);
        int limit = (c * (c - 1)) / 2;
        int count = 0;
        for (int cur = -c; cur < 0; cur++) {
            int pairs = c + cur + 1;
            int start_j = mid - cur + 1;
            int end_j = mid + limit;
            for (int j = start_j; j <= end_j; j++) {
                if (j >= 0 && j < size) {
                    long long temp_count = (long long)count + (long long)temp[j] * pairs;
                    count = (int)(temp_count % m);
                }
            }
        }
        int mult = (i == 0) ? 1 : fact[i - 1];
        long long temp_ans = (long long)ans + (long long)count * mult;
        ans = (int)(temp_ans % m);
        for (int j = mid - limit; j <= mid + limit; j++) {
            if (j >= 0 && j < size) {
                int c = n - 1 - i;
                for (int cur = -c; cur <= c; cur++) {
                    int idx = j + cur;
                    if (idx >= 0 && idx < size) {
                        int pairs = c - abs(cur) + 1;
                        long long temp_dp = (long long)dp[idx] + (long long)pairs * temp[j];
                        dp[idx] = (int)(temp_dp % m);
                    }
                }
            }
        }
    }
    std::cout << ans << std::endl;
    return 0;
}
